{
  "root_causes": [
    {
      "service": "ts-train-service",
      "fault_kind": "database_call_failed",
      "evidence": [
        {"kind": "trace", "sql": "SELECT span_name, attr_status_code, count(*) n, round(approx_quantile(duration,0.5)/1e6,1) p50_ms FROM abnormal_traces WHERE service_name='ts-train-service' AND span_name LIKE 'SELECT%' GROUP BY 1,2 ORDER BY 1,2", "claim": "Train-service SELECT TrainType/train_type DB spans all error out after about 30 s, versus about 1.5 ms in normal traffic."},
        {"kind": "log", "sql": "SELECT level, message, count(*) n FROM abnormal_logs WHERE service_name='ts-train-service' AND level IN ('ERROR','SEVERE','WARN') GROUP BY 1,2 ORDER BY n DESC LIMIT 10", "claim": "Train-service logs show Hikari connection timeouts, communications link failures and closed-connection errors on its MySQL pool."},
        {"kind": "metric", "sql": "SELECT metric, round(avg(value),2) avg_v, max(value) max_v FROM abnormal_metrics_sum WHERE service_name='ts-train-service' AND metric LIKE 'db.client.connections%' GROUP BY 1 ORDER BY 1", "claim": "Train-service DB pool shows pending requests rising from 0 to 1.5 and connection timeouts of 4 to 5, while pool usage falls."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-train-service", "to": "ts-basic-service", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name child_svc, p.service_name parent_svc, count(*) n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) child_err FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND c.parent_span_id=p.span_id WHERE c.service_name='ts-train-service' AND p.service_name='ts-basic-service' GROUP BY 1,2", "claim": "Calls from ts-basic-service to ts-train-service all error, 8 of 8, once train-service DB fails."}]},
    {"from": "ts-basic-service", "to": "ts-travel-service", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name child_svc, p.service_name parent_svc, count(*) n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) child_err FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND c.parent_span_id=p.span_id WHERE c.service_name='ts-basic-service' AND p.service_name='ts-travel-service' GROUP BY 1,2", "claim": "Calls from ts-travel-service to ts-basic-service error 4 of 4, with 60 s durations."}]},
    {"from": "ts-basic-service", "to": "ts-travel2-service", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name child_svc, p.service_name parent_svc, count(*) n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) child_err FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND c.parent_span_id=p.span_id WHERE c.service_name='ts-basic-service' AND p.service_name='ts-travel2-service' GROUP BY 1,2", "claim": "Calls from ts-travel2-service to ts-basic-service error 1 of 1 with about 60 s duration."}]},
    {"from": "ts-travel-service", "to": "ts-route-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name child_svc, p.service_name parent_svc, count(*) n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) child_err FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND c.parent_span_id=p.span_id WHERE c.service_name='ts-travel-service' AND p.service_name='ts-route-plan-service' GROUP BY 1,2", "claim": "Calls from ts-route-plan-service to ts-travel-service error 4 of 7 in abnormal traces."}]},
    {"from": "ts-travel2-service", "to": "ts-route-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name child_svc, p.service_name parent_svc, count(*) n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) child_err FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND c.parent_span_id=p.span_id WHERE c.service_name='ts-travel2-service' AND p.service_name='ts-route-plan-service' GROUP BY 1,2", "claim": "Calls from ts-route-plan-service to ts-travel2-service error 1 of 4 in abnormal traces, with 60 s timeouts."}]},
    {"from": "ts-route-plan-service", "to": "ts-travel-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name child_svc, p.service_name parent_svc, count(*) n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) child_err FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND c.parent_span_id=p.span_id WHERE c.service_name='ts-route-plan-service' AND p.service_name='ts-travel-plan-service' GROUP BY 1,2", "claim": "Calls from ts-travel-plan-service to ts-route-plan-service error 4 of 4, with 60 s durations."}]},
    {"from": "ts-travel-plan-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name child_svc, p.service_name parent_svc, count(*) n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) child_err FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND c.parent_span_id=p.span_id WHERE c.service_name='ts-travel-plan-service' AND p.service_name='ts-ui-dashboard' GROUP BY 1,2", "claim": "Calls from ts-ui-dashboard to ts-travel-plan-service error 4 of 4, so the failure reaches the user-facing dashboard."}]},
    {"from": "ts-train-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name child_svc, p.service_name parent_svc, count(*) n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) child_err FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND c.parent_span_id=p.span_id WHERE c.service_name='ts-train-service' AND p.service_name='ts-ui-dashboard' GROUP BY 1,2", "claim": "Direct calls from ts-ui-dashboard to ts-train-service error 5 of 5, so the dashboard sees the train failure too."}]}
  ]
}

